"""受注の一覧を扱う。"""

ORDERS = [
    {"id": 1, "customer": "東都商事", "amount": 12000},
    {"id": 2, "customer": "北浜物産", "amount": 8500},
]


def list_orders():
    """受注を id の順に返す。"""
    return sorted(ORDERS, key=lambda order: order["id"])

