import unittest

from orders import list_orders


class ListOrdersTest(unittest.TestCase):
    def test_orders_are_returned_in_id_order(self):
        self.assertEqual([o["id"] for o in list_orders()], [1, 2])


if __name__ == "__main__":
    unittest.main()
